src/app/profile-card.ts<pre><code>import { Component, signal } from '@angular/core';

@Component({
  selector: 'app-profile-card',
  template: `
    &lt;article [class.featured]="featured()" [style.border-color]="accent()"&gt;
      &lt;img [src]="avatarUrl()" [alt]="name() + ' avatar'" width="64" height="64" /&gt;
      &lt;h2&gt;{{ name() }}&lt;/h2&gt;
      &lt;p [attr.aria-label]="'Followers: ' + followers()"&gt;{{ followers() }} followers&lt;/p&gt;
      &lt;input #nameBox [value]="name()" (keyup.enter)="name.set(nameBox.value)" /&gt;
      &lt;button type="button" (click)="follow()"&gt;Follow&lt;/button&gt;
      &lt;button type="button" (click)="featured.set(!featured())"&gt;Toggle featured&lt;/button&gt;
    &lt;/article&gt;
  `,
  styles: `
    article { border: 2px solid; padding: 1rem; border-radius: 8px; }
    .featured { background: #fff7e0; }
    h2 { margin: 0.25rem 0; }
  `,
  host: { class: 'card', '[attr.data-followers]': 'followers()' },
})
export class ProfileCard {
  protected readonly name = signal('Ada Lovelace');
  protected readonly avatarUrl = signal('/favicon.ico');
  protected readonly followers = signal(10);
  protected readonly featured = signal(false);
  protected readonly accent = signal('#c3002f');

  protected follow() {
    this.followers.update((n) =&gt; n + 1);
  }
}
</code></pre> <p>The <code>@Component</code> metadata you will use most:</p> Property Purpose <code>selector</code> The element name that creates this component (<code>&lt;app-profile-card /&gt;</code>). Prefix with your app's prefix (<code>app-</code> by default) to avoid clashing with real or future HTML elements. <code>template</code> / <code>templateUrl</code> Inline template string, or path to an <code>.html</code> file. Use one or the other. <code>styles</code> / <code>styleUrl</code> Inline CSS string (or array), or path to a stylesheet. <code>imports</code> Components, directives and pipes this template uses. <code>host</code> Bindings and listeners on the component's own element (the <code>&lt;app-profile-card&gt;</code> tag). <code>changeDetection</code> Change detection strategy — <code>OnPush</code> by default in Angular 22 (Level 3, lesson 01). <p>Members used in the template are marked <code>protected</code>: the template can see them, but other TypeScript code that holds a reference to the component cannot. Use <code>private</code> for things the template should not touch — the compiler will report an error if the template tries.</p>

src/app/cart-summary.ts<pre><code>import { Component, computed, signal } from '@angular/core';

interface Line { name: string; price: number; qty: number }

@Component({
  selector: 'app-cart-summary',
  template: `
    &lt;ul&gt;
      @for (line of lines(); track line.name) {
        &lt;li&gt;
          {{ line.name }} × {{ line.qty }}
          &lt;button type="button" (click)="inc(line.name)"&gt;+&lt;/button&gt;
        &lt;/li&gt;
      }
    &lt;/ul&gt;
    &lt;p&gt;Items: {{ itemCount() }} — Total: {{ total() }}&lt;/p&gt;
  `,
})
export class CartSummary {
  protected readonly lines = signal&lt;Line[]&gt;([
    { name: 'Notebook', price: 4, qty: 1 },
    { name: 'Pen', price: 1.5, qty: 3 },
  ]);
  protected readonly itemCount = computed(() =&gt; this.lines().reduce((n, l) =&gt; n + l.qty, 0));
  protected readonly total = computed(() =&gt; this.lines().reduce((s, l) =&gt; s + l.price * l.qty, 0));

  protected inc(name: string) {
    this.lines.update((ls) =&gt; ls.map((l) =&gt; (l.name === name ? { ...l, qty: l.qty + 1 } : l)));
  }
}
</code></pre> <p>(<code>@for</code> is covered in the next lesson.) Clicking + updates one signal; two computed values and the list re-render; nothing else in the app is touched.</p>

src/app/order-view.ts<pre><code>import { Component, computed, signal } from '@angular/core';

type Status = 'pending' | 'shipped' | 'delivered' | 'cancelled';
interface Order { id: number; customer: string; total: number; status: Status; items: string[] }

@Component({
  selector: 'app-order-view',
  template: `
    @let open = openOrders();
    &lt;h2&gt;Orders ({{ open.length }} open)&lt;/h2&gt;

    @if (loading()) {
      &lt;p&gt;Loading…&lt;/p&gt;
    } @else if (orders().length === 0) {
      &lt;p&gt;No orders yet.&lt;/p&gt;
    } @else {
      &lt;ol&gt;
        @for (order of orders(); track order.id; let i = $index, last = $last) {
          &lt;li [class.last]="last"&gt;
            #{{ i + 1 }} {{ order.customer }} — {{ order.total }}
            @switch (order.status) {
              @case ('pending') { &lt;em&gt;awaiting payment&lt;/em&gt; }
              @case ('shipped') { &lt;strong&gt;on its way&lt;/strong&gt; }
              @case ('delivered') { &lt;span&gt;delivered&lt;/span&gt; }
              @case ('cancelled') { &lt;del&gt;cancelled&lt;/del&gt; }
              @default never;
            }
            @if (order.items[0]; as first) { (first item: {{ first }}) }
          &lt;/li&gt;
        } @empty {
          &lt;li&gt;Nothing to show.&lt;/li&gt;
        }
      &lt;/ol&gt;
    }
  `,
})
export class OrderView {
  protected readonly loading = signal(false);
  protected readonly orders = signal&lt;Order[]&gt;([
    { id: 7, customer: 'Ada', total: 42, status: 'shipped', items: ['Keyboard'] },
    { id: 9, customer: 'Linus', total: 13, status: 'pending', items: [] },
  ]);
  protected readonly openOrders = computed(() =&gt;
    this.orders().filter((o) =&gt; o.status === 'pending' || o.status === 'shipped'),
  );
}
</code></pre>

src/app/quantity.ts<pre><code>import { Component, booleanAttribute, input, model, numberAttribute, output } from '@angular/core';

@Component({
  selector: 'app-quantity',
  template: `
    &lt;button type="button" (click)="change(-1)" [disabled]="disabled() || value() &lt;= min()"&gt;−&lt;/button&gt;
    &lt;span&gt;{{ value() }}&lt;/span&gt;
    &lt;button type="button" (click)="change(1)" [disabled]="disabled() || value() &gt;= max()"&gt;+&lt;/button&gt;
  `,
})
export class Quantity {
  readonly value = model(1);
  readonly min = input(0, { transform: numberAttribute });
  readonly max = input.required({ transform: numberAttribute });
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly limitReached = output&lt;'min' | 'max'&gt;();

  protected change(delta: number) {
    const next = this.value() + delta;
    this.value.set(next);
    if (next === this.max()) this.limitReached.emit('max');
    if (next === this.min()) this.limitReached.emit('min');
  }
}
</code></pre> <p>And a parent using it:</p> src/app/cart-line.ts<pre><code>import { Component, signal } from '@angular/core';
import { Quantity } from './quantity';

@Component({
  selector: 'app-cart-line',
  imports: [Quantity],
  template: `
    &lt;app-quantity [(value)]="qty" max="3" (limitReached)="onLimit($event)" /&gt;
    &lt;p&gt;You are buying {{ qty() }}.&lt;/p&gt;
    &lt;app-quantity [value]="5" max="9" disabled /&gt;
  `,
})
export class CartLine {
  protected readonly qty = signal(2);
  protected onLimit(which: 'min' | 'max') {
    console.log(`hit the ${which}imum`);
  }
}
</code></pre>

src/app/logger.ts<pre><code>import { Service } from '@angular/core';

@Service()
export class Logger {
  readonly lines: string[] = [];

  log(msg: string) {
    this.lines.push(msg);
    console.log(msg);
  }
}
</code></pre> <p>Use it from any component, directive, pipe or other service with <code>inject()</code>:</p> src/app/save-button.ts<pre><code>import { Component, inject } from '@angular/core';
import { Logger } from './logger';

@Component({
  selector: 'app-save-button',
  template: `&lt;button type="button" (click)="save()"&gt;Save&lt;/button&gt;`,
})
export class SaveButton {
  private readonly logger = inject(Logger);

  protected save() {
    this.logger.log('saved');
  }
}
</code></pre> <p>That's the whole pattern. You never write <code>new Logger()</code>. The first time anything injects <code>Logger</code>, Angular creates one instance; everyone after that gets the same instance for the lifetime of the app.</p>

src/app/app.ts<pre><code>import { Component } from '@angular/core';
import { RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink, RouterLinkActive],
  template: `
    &lt;header&gt;
      &lt;nav&gt;
        &lt;a routerLink="/books" routerLinkActive="active"&gt;My books&lt;/a&gt;
        &lt;a routerLink="/search" routerLinkActive="active" ariaCurrentWhenActive="page"&gt;Search&lt;/a&gt;
      &lt;/nav&gt;
    &lt;/header&gt;
    &lt;main&gt;&lt;router-outlet /&gt;&lt;/main&gt;
  `,
