</code></pre> <p>The header stays; whatever the current route matches is rendered right after <code>&lt;router-outlet /&gt;</code>.</p>

src/app/reading/book.ts<pre><code>export type Status = 'want' | 'reading' | 'done';

export interface Book {
  id: string;
  title: string;
  author: string;
  status: Status;
  rating: number; // 0 = not rated
}
</code></pre> <p><code>rating</code> uses <code>0</code> for "not rated" rather than <code>undefined</code>, which keeps the JSON in <code>localStorage</code> simple and avoids optional-chaining everywhere.</p>

src/app/reading/star-rating.ts<pre><code>import { Component, input, model } from '@angular/core';

@Component({
  selector: 'app-star-rating',
  template: `
    &lt;span role="radiogroup" [attr.aria-label]="label()"&gt;
      @for (star of stars; track star) {
        &lt;button
          type="button"
          role="radio"
          [attr.aria-checked]="star === value()"
          [attr.aria-label]="star + ' of 5'"
          [class.on]="star &lt;= value()"
          (click)="value.set(star === value() ? 0 : star)"&gt;★&lt;/button&gt;
      }
    &lt;/span&gt;
  `,
  styles: `
    button { border: 0; background: none; font-size: 1.25rem; color: #bbb; cursor: pointer; }
    button.on { color: #e0a100; }
  `,
})
export class StarRating {
  readonly value = model(0);
  readonly label = input('Rating');
  protected readonly stars = [1, 2, 3, 4, 5];
}
</code></pre> <p><code>value</code> is a <code>model()</code>, so a parent can use <code>[(value)]</code> or, as below, bind the input and the <code>valueChange</code> output separately. Clicking the current star again clears the rating. The radio-group roles and labels give screen-reader users a meaningful control, not five unlabeled "★" buttons.</p>

src/app/reading/book-card.ts<pre><code>import { Component, input, output } from '@angular/core';
import { RouterLink } from '@angular/router';
import { Book, Status } from './book';
import { StarRating } from './star-rating';

@Component({
  selector: 'app-book-card',
  imports: [RouterLink, StarRating],
  template: `
    &lt;article&gt;
      &lt;h3&gt;&lt;a [routerLink]="['/books', book().id]"&gt;{{ book().title }}&lt;/a&gt;&lt;/h3&gt;
      &lt;p&gt;{{ book().author }}&lt;/p&gt;
      &lt;select [value]="book().status" (change)="statusChange.emit(asStatus($event))" aria-label="Status"&gt;
        &lt;option value="want"&gt;Want to read&lt;/option&gt;
        &lt;option value="reading"&gt;Reading&lt;/option&gt;
        &lt;option value="done"&gt;Done&lt;/option&gt;
      &lt;/select&gt;
      @if (book().status === 'done') {
        &lt;app-star-rating [value]="book().rating" (valueChange)="rated.emit($event)" /&gt;
      }
      &lt;button type="button" (click)="removed.emit()"&gt;Remove&lt;/button&gt;
    &lt;/article&gt;
  `,
})
export class BookCard {
  readonly book = input.required&lt;Book&gt;();
  readonly statusChange = output&lt;Status&gt;();
  readonly rated = output&lt;number&gt;();
  readonly removed = output&lt;void&gt;();

  protected asStatus(event: Event) {
    return (event.target as HTMLSelectElement).value as Status;
  }
}
</code></pre> <p>The card is presentational: it receives a <code>book</code> and emits intentions (<code>statusChange</code>, <code>rated</code>, <code>removed</code>). It doesn't know the store exists, which makes it trivial to reuse and to test with a plain input.</p>

src/app/reading/book-list.ts<pre><code>import { Component, computed, inject, signal } from '@angular/core';
import { BookCard } from './book-card';
import { BookStore } from './book-store';
import { Status } from './book';

type Filter = Status | 'all';

@Component({
  selector: 'app-book-list',
  imports: [BookCard],
  template: `
    &lt;h2&gt;My books&lt;/h2&gt;
    &lt;nav aria-label="Filter"&gt;
      @for (f of filters; track f) {
        &lt;button type="button" [attr.aria-pressed]="filter() === f" (click)="filter.set(f)"&gt;
          {{ f }} @if (f !== 'all') { ({{ store.counts()[f] }}) }
        &lt;/button&gt;
      }
    &lt;/nav&gt;

    &lt;form (submit)="add($event, title.value, author.value); title.value = ''; author.value = ''"&gt;
      &lt;input #title placeholder="Title" required /&gt;
      &lt;input #author placeholder="Author" required /&gt;
      &lt;button&gt;Add&lt;/button&gt;
    &lt;/form&gt;

    @for (book of visible(); track book.id) {
      &lt;app-book-card
        [book]="book"
        (statusChange)="store.setStatus(book.id, $event)"
        (rated)="store.rate(book.id, $event)"
        (removed)="store.remove(book.id)" /&gt;
    } @empty {
      &lt;p&gt;No books here yet.&lt;/p&gt;
    }
  `,
})
export class BookList {
  protected readonly store = inject(BookStore);
  protected readonly filters: Filter[] = ['all', 'want', 'reading', 'done'];
  protected readonly filter = signal&lt;Filter&gt;('all');
  protected readonly visible = computed(() =&gt; {
    const f = this.filter();
    const books = this.store.books();
    return f === 'all' ? books : books.filter((b) =&gt; b.status === f);
  });

  protected add(event: Event, title: string, author: string) {
    event.preventDefault();
    if (title.trim() &amp;&amp; author.trim()) this.store.add(title.trim(), author.trim());
  }
}
</code></pre> <p><code>visible</code> is derived from two signals — the store's books and the local filter — so changing either re-renders the list and nothing else. The filter buttons expose their state with <code>aria-pressed</code>.</p>

src/app/reading/book-detail.ts<pre><code>import { Component, computed, inject, input } from '@angular/core';
import { RouterLink } from '@angular/router';
import { BookStore } from './book-store';

@Component({
  selector: 'app-book-detail',
  imports: [RouterLink],
  template: `
    @if (book(); as b) {
      &lt;h2&gt;{{ b.title }}&lt;/h2&gt;
      &lt;p&gt;by {{ b.author }} — {{ b.status }}&lt;/p&gt;
    } @else {
      &lt;p&gt;No book with id “{{ id() }}”.&lt;/p&gt;
    }
    &lt;a routerLink="/books"&gt;← Back&lt;/a&gt;
  `,
})
export class BookDetail {
  readonly id = input.required&lt;string&gt;(); // filled from the :id route parameter
  private readonly store = inject(BookStore);
  protected readonly book = computed(() =&gt; this.store.byId(this.id()));
}
</code></pre> <p><code>id</code> is filled from the <code>:id</code> route parameter because the app enables <code>withComponentInputBinding()</code> (next step). <code>book</code> is a <code>computed</code> over the input and the store, so it stays correct if the router reuses the component for another id, and it also updates if the book is edited elsewhere.</p>

src/app/app.routes.ts<pre><code>import { Routes } from '@angular/router';
