src/app/reading/book-store.spec.ts<pre><code>import { TestBed } from '@angular/core/testing';
import { BookStore } from './book-store';

describe('BookStore', () =&gt; {
  beforeEach(() =&gt; localStorage.clear());

  it('adds books and counts them by status', () =&gt; {
    const store = TestBed.inject(BookStore);
    store.add('Dune', 'Frank Herbert');
    store.add('Piranesi', 'Susanna Clarke');
    const [dune] = store.books();
    store.setStatus(dune.id, 'done');
    store.rate(dune.id, 4);

    expect(store.counts()).toEqual({ want: 1, reading: 0, done: 1 });
    expect(store.byId(dune.id)?.rating).toBe(4);
  });

  it('persists to localStorage', () =&gt; {
    const store = TestBed.inject(BookStore);
    store.add('Dune', 'Frank Herbert');
    TestBed.tick(); // flush the effect
    const saved = JSON.parse(localStorage.getItem('reading-list')!);
    expect(saved[0].title).toBe('Dune');
  });
});
</code></pre> <p>Note <code>TestBed.tick()</code> in the second test: effects run asynchronously, so a test that checks what an effect did must flush them first. Add the <code>OpenLibrary</code> test from lesson 09 as <code>src/app/reading/open-library.spec.ts</code>.</p>

src/app/signup-form.ts<pre><code>import { Component, inject, signal } from '@angular/core';
import { AbstractControl, NonNullableFormBuilder, ReactiveFormsModule, ValidationErrors, ValidatorFn, Validators } from '@angular/forms';
import { toSignal } from '@angular/core/rxjs-interop';

export const passwordsMatch: ValidatorFn = (group: AbstractControl): ValidationErrors | null =&gt; {
  const pw = group.get('password')?.value;
  const confirm = group.get('confirm')?.value;
  return pw &amp;&amp; confirm &amp;&amp; pw !== confirm ? { passwordsMismatch: true } : null;
};

export function forbiddenWords(words: string[]): ValidatorFn {
  return (control) =&gt; {
    const v = String(control.value ?? '').toLowerCase();
    const hit = words.find((w) =&gt; v.includes(w));
    return hit ? { forbidden: { word: hit } } : null;
  };
}

@Component({
  selector: 'app-signup-form',
  imports: [ReactiveFormsModule],
  template: `
    &lt;form [formGroup]="form" (ngSubmit)="submit()"&gt;
      &lt;label&gt;Username &lt;input formControlName="username" autocomplete="username" /&gt;&lt;/label&gt;
      @if (form.controls.username.touched &amp;&amp; form.controls.username.errors; as e) {
        @if (e['required']) { &lt;p class="err"&gt;Username is required.&lt;/p&gt; }
        @if (e['minlength']) { &lt;p class="err"&gt;At least {{ e['minlength'].requiredLength }} characters.&lt;/p&gt; }
        @if (e['forbidden']) { &lt;p class="err"&gt;“{{ e['forbidden'].word }}” is not allowed.&lt;/p&gt; }
      }

      &lt;label&gt;Email &lt;input formControlName="email" type="email" autocomplete="email" /&gt;&lt;/label&gt;

      &lt;fieldset formGroupName="passwords"&gt;
        &lt;label&gt;Password &lt;input formControlName="password" type="password" autocomplete="new-password" /&gt;&lt;/label&gt;
        &lt;label&gt;Confirm &lt;input formControlName="confirm" type="password" autocomplete="new-password" /&gt;&lt;/label&gt;
        @if (form.controls.passwords.errors?.['passwordsMismatch']) { &lt;p class="err"&gt;Passwords don't match.&lt;/p&gt; }
      &lt;/fieldset&gt;

      &lt;fieldset&gt;
        &lt;legend&gt;Interests&lt;/legend&gt;
        @for (ctrl of interests.controls; track ctrl; let i = $index) {
          &lt;input [formControl]="ctrl" [attr.aria-label]="'Interest ' + (i + 1)" /&gt;
          &lt;button type="button" (click)="interests.removeAt(i)"&gt;✕&lt;/button&gt;
        }
        &lt;button type="button" (click)="addInterest()"&gt;Add interest&lt;/button&gt;
      &lt;/fieldset&gt;

      &lt;label&gt;&lt;input type="checkbox" formControlName="terms" /&gt; I accept the terms&lt;/label&gt;

      &lt;button [disabled]="form.invalid || submitting()"&gt;Sign up&lt;/button&gt;
      &lt;p&gt;Status: {{ status() }}&lt;/p&gt;
    &lt;/form&gt;
  `,
})
export class SignupForm {
  private readonly fb = inject(NonNullableFormBuilder);
  protected readonly submitting = signal(false);
  readonly submitted = signal&lt;unknown&gt;(null);

  readonly form = this.fb.group({
    username: ['', [Validators.required, Validators.minLength(3), forbiddenWords(['admin', 'root'])]],
    email: ['', [Validators.required, Validators.email]],
    passwords: this.fb.group(
      { password: ['', [Validators.required, Validators.minLength(8)]], confirm: [''] },
      { validators: passwordsMatch },
    ),
    interests: this.fb.array([this.fb.control('')]),
    terms: [false, Validators.requiredTrue],
  });

  protected readonly status = toSignal(this.form.statusChanges, { initialValue: this.form.status });

  protected get interests() {
    return this.form.controls.interests;
  }

  protected addInterest() {
    this.interests.push(this.fb.control(''));
  }

  protected submit() {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.submitted.set(this.form.getRawValue());
    this.form.reset();
  }
}
</code></pre>

src/app/signup-signal-form.ts<pre><code>import { Component, signal } from '@angular/core';
import {
  FormField, applyEach, disabled, email, form, maxLength, min, minLength, required, submit, validate,
} from '@angular/forms/signals';

interface Signup {
  username: string;
  email: string;
  password: string;
  confirm: string;
  age: number | null;
  interests: string[];
  terms: boolean;
}

const empty: Signup = {
  username: '', email: '', password: '', confirm: '', age: null, interests: [''], terms: false,
};

@Component({
  selector: 'app-signup-signal-form',
  imports: [FormField],
  template: `
    &lt;form (submit)="onSubmit($event)" novalidate&gt;
      &lt;label&gt;Username &lt;input [formField]="f.username" autocomplete="username" /&gt;&lt;/label&gt;
      @if (f.username().touched()) {
        @for (e of f.username().errors(); track e.kind) { &lt;p class="err"&gt;{{ e.message }}&lt;/p&gt; }
      }

      &lt;label&gt;Email &lt;input type="email" [formField]="f.email" /&gt;&lt;/label&gt;
      &lt;label&gt;Age &lt;input type="number" [formField]="f.age" /&gt;&lt;/label&gt;

      &lt;label&gt;Password &lt;input type="password" [formField]="f.password" /&gt;&lt;/label&gt;
      &lt;label&gt;Confirm &lt;input type="password" [formField]="f.confirm" /&gt;&lt;/label&gt;
      @for (e of f.confirm().errors(); track e.kind) { &lt;p class="err"&gt;{{ e.message }}&lt;/p&gt; }

      &lt;fieldset&gt;
        &lt;legend&gt;Interests&lt;/legend&gt;
        @for (item of f.interests; track item; let i = $index) {
          &lt;input [formField]="item" [attr.aria-label]="'Interest ' + (i + 1)" /&gt;
        }
        &lt;button type="button" (click)="addInterest()"&gt;Add interest&lt;/button&gt;
      &lt;/fieldset&gt;

      &lt;label&gt;&lt;input type="checkbox" [formField]="f.terms" /&gt; I accept the terms&lt;/label&gt;

      &lt;button [disabled]="f().submitting()"&gt;Sign up&lt;/button&gt;
      &lt;p&gt;Valid: {{ f().valid() }}&lt;/p&gt;
    &lt;/form&gt;
  `,
})
export class SignupSignalForm {
  readonly model = signal&lt;Signup&gt;({ ...empty });
  readonly saved = signal&lt;Signup | null&gt;(null);

  readonly f = form(this.model, (p) =&gt; {
    required(p.username, { message: 'Username is required.' });
    minLength(p.username, 3, { message: 'At least 3 characters.' });
    validate(p.username, ({ value }) =&gt;
      /admin|root/i.test(value()) ? { kind: 'forbidden', message: 'That name is reserved.' } : null,
    );
    required(p.email, { message: 'Email is required.' });
    email(p.email, { message: 'Enter a valid email.' });
    min(p.age, 13, { message: 'You must be 13 or older.' });
    required(p.password);
    minLength(p.password, 8, { message: 'Use at least 8 characters.' });
    disabled(p.confirm, ({ valueOf }) =&gt; valueOf(p.password) === '');
    validate(p.confirm, ({ value, valueOf }) =&gt;
      value() !== valueOf(p.password) ? { kind: 'mismatch', message: "Passwords don't match." } : null,
    );
    applyEach(p.interests, (item) =&gt; maxLength(item, 20, { message: 'Keep it under 20 characters.' }));
    required(p.terms, { message: 'Please accept the terms.' });
  });

  protected addInterest() {
    this.model.update((m) =&gt; ({ ...m, interests: [...m.interests, ''] }));
  }

  protected async onSubmit(event: Event) {
    event.preventDefault();
    await submit(this.f, {
      action: async () =&gt; {
        await new Promise((r) =&gt; setTimeout(r, 10)); // stand-in for an HTTP call
        if (this.model().username === 'taken') {
          return [{ fieldTree: this.f.username, kind: 'server', message: 'Username already taken.' }];
        }
        this.saved.set(this.model());
        return undefined;
      },
    });
  }
}
</code></pre>

src/app/user-card.ts<pre><code>import { Component, input } from '@angular/core';
import { httpResource } from '@angular/common/http';

interface User { id: number; name: string; email: string }

@Component({
  selector: 'app-user-card',
  template: `
    @if (user.error(); as err) {
      &lt;p role="alert"&gt;Could not load user {{ id() }}.&lt;/p&gt;
      &lt;button type="button" (click)="user.reload()"&gt;Try again&lt;/button&gt;
    } @else if (user.hasValue()) {
      &lt;h2&gt;{{ user.value().name }}&lt;/h2&gt;
      &lt;p&gt;{{ user.value().email }}&lt;/p&gt;
    }
    @if (user.isLoading()) {
      &lt;p aria-live="polite"&gt;Loading…&lt;/p&gt;
    }
  `,
})
export class UserCard {
  readonly id = input.required&lt;number&gt;();
  protected readonly user = httpResource&lt;User&gt;(() =&gt; `/api/users/${this.id()}`);
}
</code></pre> <p>That's the whole data layer for this component. When <code>id</code> changes, the resource computes the new URL and fetches it; if a request is still in flight for the previous id, it's cancelled. We rendered it under the HTTP testing backend and recorded the text at each step:</p> <pre><code>T1  Loading…                                     (request for /api/users/1 outstanding)
T2  Ada ada@example.com                          (flushed 200)
T3  Could not load user 2. Try again             (id → 2, flushed 500)
T4  Could not load user 2. Try again Loading…    (clicked Try again → reload())
T5  Grace grace@example.com                      (flushed 200)
</code></pre> <p>The request function can return a URL string or a request object — <code>{ url, method, params, headers, body, ... }</code> — for anything beyond a simple GET. Returning <code>undefined</code> means "nothing to load right now" and leaves the resource idle:</p> <pre><code>protected readonly query = signal('');
protected readonly results = httpResource&lt;User[]&gt;(
  () =&gt; (this.query() ? { url: '/api/users', params: { q: this.query() } } : undefined),
  { defaultValue: [] },
);
</code></pre> <p>With an empty query this stayed <code>idle</code> with value <code>[]</code>; setting <code>query</code> to <code>gr</code> sent <code>GET /api/users?q=gr</code> and resolved to the flushed array.</p> <p><code>httpResource</code> also exposes the response's <code>headers()</code> and <code>statusCode()</code> as signals, and has variants for non-JSON bodies: <code>httpResource.text()</code>, <code>httpResource.blob()</code>, <code>httpResource.arrayBuffer()</code>. Pass <code>parse: (raw) =&gt; ...</code> to validate or transform the JSON (a natural place for a schema library).</p> <p>Reads, not writes</p> <p><code>httpResource</code> is designed for fetching data that depends on signals. For POST, PUT and DELETE triggered by a user action, call <code>HttpClient</code> directly (or use <code>submit()</code> in signal forms). A resource re-runs whenever its params change, which is exactly wrong for "create an order".</p>

