src/app/search-box.ts<pre><code>@Component({
  selector: 'app-search-box',
  template: `&lt;input #box type="search" [placeholder]="placeholder()" /&gt; &lt;button type="button" (click)="focus()"&gt;Focus&lt;/button&gt;`,
})
export class SearchBox {
