  private readonly box = viewChild.required&lt;ElementRef&lt;HTMLInputElement&gt;&gt;('box');
  focus() { this.box().nativeElement.focus(); }
}
</code></pre> <p><code>viewChild.required&lt;ElementRef&lt;HTMLInputElement&gt;&gt;('box')</code> finds the element with the <code>#box</code> reference in this component's template. Clicking Focus focused the input (<code>document.activeElement</code> was the <code>INPUT</code> of type <code>search</code>). The four query functions:</p> Query Looks in Returns <code>viewChild(x)</code> / <code>viewChild.required(x)</code> this component's own template <code>Signal&lt;T \| undefined&gt;</code> / <code>Signal&lt;T&gt;</code> <code>viewChildren(x)</code> own template <code>Signal&lt;readonly T[]&gt;</code> <code>contentChild(x)</code> / <code>.required</code> projected content <code>Signal&lt;T \| undefined&gt;</code> / <code>Signal&lt;T&gt;</code> <code>contentChildren(x)</code> projected content <code>Signal&lt;readonly T[]&gt;</code> <p><code>x</code> is a template reference name (<code>'box'</code>), a component/directive class, or a token such as <code>TemplateRef</code>. Use <code>{ read: ElementRef }</code> to get a different thing from the matched node — for example the element of a component instead of its instance.</p> <p>Because queries are signals, they update when content appears or disappears: they can feed <code>computed</code> and <code>effect</code>, and there's no <code>ngAfterViewInit</code> timing to get right. Don't read them in the constructor — nothing has rendered yet; read them in templates, computeds, event handlers or <code>afterNextRender</code>.</p>

src/app/tabs.ts<pre><code>@Component({
  selector: 'app-tab',
  host: { role: 'tabpanel', '[hidden]': '!active()' },
  template: `&lt;ng-content /&gt;`,
})
export class Tab {
  readonly label = input.required&lt;string&gt;();
  private readonly tabs = inject(Tabs);
  readonly active = computed(() =&gt; this.tabs.selectedTab() === this);
}

@Component({
  selector: 'app-tabs',
  template: `
    &lt;div role="tablist"&gt;
      @for (tab of tabs(); track tab; let i = $index) {
        &lt;button role="tab" type="button" [attr.aria-selected]="tab.active()" (click)="selectedIndex.set(i)"&gt;
          {{ tab.label() }}
        &lt;/button&gt;
      }
    &lt;/div&gt;
    &lt;ng-content /&gt;
  `,
})
export class Tabs {
  protected readonly tabs = contentChildren(Tab);
  readonly selectedIndex = signal(0);
  readonly selectedTab = computed(() =&gt; this.tabs()[this.selectedIndex()]);
  readonly count = computed(() =&gt; this.tabs().length);
}
</code></pre> <pre><code>&lt;app-tabs #tabs&gt;
  &lt;app-tab label="Overview"&gt;Overview body&lt;/app-tab&gt;
  &lt;app-tab label="Details"&gt;Details body&lt;/app-tab&gt;
  @if (showExtra()) { &lt;app-tab label="Extra"&gt;Extra body&lt;/app-tab&gt; }
&lt;/app-tabs&gt;
&lt;p&gt;{{ tabs.count() }} tabs&lt;/p&gt;
</code></pre> <p>Observed:</p> <pre><code>initially        panels: ['Overview body', '(hidden)']     count 2
click "Details"  panels: ['(hidden)', 'Details body']
showExtra → true tabs:   ['Overview', 'Details', 'Extra']  count 3
</code></pre> <p>Notice the design: <code>Tabs</code> owns one piece of state (<code>selectedIndex</code>) and derives <code>selectedTab</code>; each <code>Tab</code> injects its parent (a component can inject any ancestor component) and derives its own <code>active</code> with <code>computed</code>. No effects, no manual syncing, no lifecycle hooks — and adding a tab later just works, because <code>contentChildren</code> is a signal and everything downstream recomputes.</p>

