src/app/reading/book-card.spec.ts<pre><code>import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { BookCard } from './book-card';
import { Book } from './book';

const dune: Book = { id: 'b1', title: 'Dune', author: 'Frank Herbert', status: 'want', rating: 0 };

describe('BookCard', () =&gt; {
  async function setup(book: Book) {
    TestBed.configureTestingModule({ providers: [provideRouter([])] });
    const fixture = TestBed.createComponent(BookCard);
    fixture.componentRef.setInput('book', book);
    await fixture.whenStable();
    return { fixture, el: fixture.nativeElement as HTMLElement };
  }

  it('renders the title as a link to the detail page', async () =&gt; {
    const { el } = await setup(dune);
    const link = el.querySelector('h3 a')!;
    expect(link.textContent).toBe('Dune');
    expect(link.getAttribute('href')).toBe('/books/b1');
  });

  it('only shows the rating control for finished books', async () =&gt; {
    const { fixture, el } = await setup(dune);
    expect(el.querySelector('app-star-rating')).toBeNull();

    fixture.componentRef.setInput('book', { ...dune, status: 'done' });
    await fixture.whenStable();
    expect(el.querySelector('app-star-rating')).not.toBeNull();
  });

  it('emits statusChange when a new status is selected', async () =&gt; {
    const { fixture, el } = await setup(dune);
    const emitted: string[] = [];
    fixture.componentInstance.statusChange.subscribe((s) =&gt; emitted.push(s));

    const select = el.querySelector('select')!;
    select.value = 'reading';
    select.dispatchEvent(new Event('change'));

    expect(emitted).toEqual(['reading']);
  });

  it('emits removed when Remove is clicked', async () =&gt; {
    const { fixture, el } = await setup(dune);
    const removed = vi.fn();
    fixture.componentInstance.removed.subscribe(removed);

    el.querySelector&lt;HTMLButtonElement&gt;('button[type=button]:last-of-type')!.click();

    expect(removed).toHaveBeenCalledTimes(1);
  });
});
</code></pre> <p>The pattern, in four moves:</p> <ol> <li>Configure only what the component needs (<code>provideRouter([])</code> because the card    uses <code>routerLink</code>).</li> <li>Create it and set inputs with <code>fixture.componentRef.setInput(...)</code> — the same path    a parent template uses, including transforms and required-input checks.</li> <li>Wait with <code>await fixture.whenStable()</code>. In a zoneless, OnPush app, rendering is    scheduled, not synchronous (lesson 01). <code>whenStable</code> waits for pending renders and    pending tasks. (<code>fixture.detectChanges()</code> still exists and forces a synchronous pass,    but <code>whenStable</code> tests the scheduling your users actually get.)</li> <li>Assert on what a user would see: text, attributes (<code>href</code>, <code>aria-pressed</code>),    presence of elements — and on outputs, by subscribing to the <code>OutputEmitterRef</code>.</li> </ol> <p>Avoid asserting on private fields or calling protected methods directly. If a test only passes because it reaches into internals, it will break on every refactor that doesn't change behaviour.</p>

