&lt;/body&gt;
&lt;/html&gt;
</code></pre> <p>We served the build and drove the element from JavaScript in Chromium:</p> <pre><code>1 initial (value="2")        2 stars on | aria-label: Article rating
2 clicked 4th star           4 on | "You rated 4"
3 r.value = 1   (property)   1 on | property reads 1
4 r.setAttribute('value','5') 5 on | typeof r.value: string, "5"
5 created with createElement 5 buttons, label "Second"
console errors: none
</code></pre> <p>The mapping from Angular to DOM:</p> Angular Custom element <code>input()</code> / <code>model()</code> named <code>label</code> attribute <code>label</code> and property <code>label</code> (camelCase inputs map to dash-case attributes: <code>maxValue</code> → <code>max-value</code>) <code>output()</code> / <code>model()</code> change named <code>valueChange</code> DOM <code>CustomEvent</code> <code>valueChange</code>, payload in <code>event.detail</code> component creation when the element is connected to the document component destruction shortly after the element is disconnected

src/app/core/error-reporter.ts<pre><code>import { ErrorDetails, ErrorHandler, Service, inject } from '@angular/core';
import { Router } from '@angular/router';

declare const BUILD_VERSION: string;

export interface ErrorReport {
  message: string;
  stack?: string;
  url: string;
  release: string;
  count: number;
}

/**
 * Collects errors, deduplicates them and (in a real deployment) ships them to a
 * monitoring endpoint. Here the transport is console.error so the behaviour is visible.
 */
@Service({ autoProvided: false })
export class ErrorReporter implements ErrorHandler {
  private readonly router = inject(Router);
  private readonly seen = new Map&lt;string, ErrorReport&gt;();

  handleError(error: unknown): void {
    this.record(error);
  }

  onViewError(error: Error, details: ErrorDetails): void {
    this.record(error, details.declarationType.name);
  }

  reports(): ErrorReport[] {
    return [...this.seen.values()];
  }

  private record(error: unknown, where?: string) {
    const err = error instanceof Error ? error : new Error(String(error));
    const key = `${err.message}|${err.stack?.split('\n')[1] ?? ''}`;
    const existing = this.seen.get(key);
    if (existing) {
      existing.count++;
      return; // already reported: don't flood the monitoring service
    }
    const report: ErrorReport = {
      message: where ? `[${where}] ${err.message}` : err.message,
      stack: err.stack,
      url: this.router.url,
      release: BUILD_VERSION,
      count: 1,
    };
    this.seen.set(key, report);
    console.error('[error report]', JSON.stringify({ message: report.message, url: report.url, release: report.release }));
  }
}
</code></pre> <p>It deduplicates by message and first stack frame (lesson 08 showed rendering errors repeat on every refresh), records the route and release, and implements <code>onViewError</code> so errors caught by <code>@boundary</code> blocks arrive with the component type. In production, replace <code>console.error</code> with a batched <code>fetch</code>/<code>navigator.sendBeacon</code> to your monitoring endpoint.</p>

src/app/core/chunk-reload.ts<pre><code>import { NavigationError } from '@angular/router';

const KEY = 'reloaded-for-release';
declare const BUILD_VERSION: string;

/** After a deploy, old chunk names 404. Reload once per release to pick up the new ones. */
export function reloadOnMissingChunk(e: NavigationError): void {
  const missingChunk = String(e.error).includes('Failed to fetch dynamically imported module');
  if (!missingChunk || typeof window === 'undefined') return;
  if (sessionStorage.getItem(KEY) === BUILD_VERSION) return; // already tried: avoid a loop
  sessionStorage.setItem(KEY, BUILD_VERSION);
  window.location.assign(e.url);
}
</code></pre>

src/app/app.config.ts<pre><code>import { ApplicationConfig, ErrorHandler, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideClientHydration, withEventReplay } from '@angular/platform-browser';
import { provideRouter, withComponentInputBinding, withNavigationErrorHandler } from '@angular/router';
import { reloadOnMissingChunk } from './core/chunk-reload';
import { ErrorReporter } from './core/error-reporter';
import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(routes, withComponentInputBinding(), withNavigationErrorHandler(reloadOnMissingChunk)),
    ErrorReporter,
    { provide: ErrorHandler, useExisting: ErrorReporter },
    provideHttpClient(),
    provideClientHydration(withEventReplay()),
  ],
};
</code></pre>
